void set_global_template_flags ( const char * name , unsigned int flags ) { if ( global_template_dict == NULL ) { global_template_dict = mowgli_patricia_create ( strcasecanon ) ; } struct default_template * def_t = mowgli_patricia_retrieve ( global_template_dict , name ) ; def_t = smalloc ( sizeof def_t ) ; def_t -> flags = flags ; mowgli_patricia_add ( global_template_dict , name , def_t ) ; slog ( LG_DEBUG , "set_global_template_flags(): add %s" , name ) ; } 